	/*
     * @param	event CreatePaymentMethodEvent
     */
    @EventHandler( payloadType=CreatePaymentMethodEvent.class )
    public void handle( CreatePaymentMethodEvent event) {
	    LOGGER.info("handling CreatePaymentMethodEvent - " + event );
	    PaymentMethod entity = new PaymentMethod();
            entity.setPaymentMethodId( event.getPaymentMethodId() );
            entity.setLast4( event.getLast4() );
            entity.setCardholderName( event.getCardholderName() );
            entity.setBillingAddress( event.getBillingAddress() );
            entity.setMethodType( event.getMethodType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPaymentMethod( entity );
    }

    /*
     * @param	event UpdatePaymentMethodEvent
     */
    @EventHandler( payloadType=UpdatePaymentMethodEvent.class )
    public void handle( UpdatePaymentMethodEvent event) {
    	LOGGER.info("handling UpdatePaymentMethodEvent - " + event );
    	
	    PaymentMethod entity = new PaymentMethod();
            entity.setPaymentMethodId( event.getPaymentMethodId() );
            entity.setLast4( event.getLast4() );
            entity.setCardholderName( event.getCardholderName() );
            entity.setBillingAddress( event.getBillingAddress() );
            entity.setBillingProfile( event.getBillingProfile() );
            entity.setMethodType( event.getMethodType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindPaymentMethod( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPaymentMethod( entity );        
    }
    
